    },
    {
      "location": "left to right, x≈300-1900",
      "fact": "Five other bars (Apr, Jan, Jun, Feb, Mar) are tall dark-red rectangles ranging from about 17,500 to 40,000 on the y-axis."
    },
    {
      "location": "full plot area",
      "fact": "All bars share the same dark-red fill; the May bar is visually the smallest by a large margin."
    }
  ],
  "printed_facts": [
    {
      "location": "y-axis",
      "fact": "Axis label 'Pumping volume (m3)' with ticks at 10,000, 15,000, 20,000, 25,000, 30,000, 35,000, 40,000."
    },
    {
      "location": "x-axis",
      "fact": "Axis label 'Month' with categories in order: Apr, Jan, Jun, Feb, Mar, May."
    },
    {
      "location": "bar tops",
      "fact": "Approximate values: Apr ≈ 29,500; Jan ≈ 40,000; Jun ≈ 17,500; Feb ≈ 20,000; Mar ≈ 27,000; May ≈ 800 (well under 10,000)."
    },
    {
      "location": "title",
      "fact": "Chart title 'Monthly Water Pumping Volume'."
    }
  ],
  "public_definitions": [
    "Routing criterion field: 'May low-pumping severity route'.",
    "Option: 'Route May to standard low-pumping follow-up'.",
    "Option: 'Escalate May to critical low-pumping anomaly review'.",
    "Option: 'Send May to background monthly record filing'."
  ],
  "uncertain": [
    "No explicit numeric threshold on the chart distinguishes 'standard follow-up' from 'critical anomaly'; the May value is read as approximately 800 m3, clearly the lowest bar.",
    "No data labels are printed on the bars, so the May value is estimated from its position relative to the 10,000 tick."
  ]
